function eb.skinPlan()
local dn,en=H.session(),H.prof()
local fn=H.data(qtc[1567])or{}
local gn=(en.inventory and en.inventory.unique_items)or en.unique_items or{}
local hn,jn={},{kinds={},sell={},wear={},pearls=0,missing={}}
