function db.xpGuess(SL)
local TL=SL.level and H.Levels[SL.level]
if not TL then
return 0
end
local UL=math.min(9,tonumber(TL.story_world_rank)or tonumber(SL.rank)or 9)
local VL=tonumber(TL.story_level_rank)or 6
local WL=(SL.kind==qtc[1467]and 1.5 or 1)*(UL>5 and 2 or 1)
local XL=2.1564^(UL-1)*(40+10*VL)/WL
if SL.kind==qtc[1450]then
XL=3*30*2.1564^(UL-1)/WL
end
local YL=UL>=9 and 0.3 or(UL>=7 and 0.5 or 1)
return XL*YL*6
end
