function P.smartEvolve()
if not I.smartEvolve then
return j.status(qtc[2239],qtc[2240])
end
local gT=H.session()
if not gT then
return
end
local hT={}
for iT,jT in ipairs(J.goals or{})do
table.insert(hT,jT)
end
table.sort(hT,function(kT,lT)
return(kT.gain or 0)>(lT.gain or 0)
end)
local mT={}
for nT,oT in ipairs(N.equipped())do
mT[oT.uuid]=true
end
local pT,qT,rT={},0,{}
for sT,tT in ipairs(hT)do
if tT.pinned then
for uT,vT in ipairs(tT.items or{})do
pT[vT.id]=(pT[vT.id]or 0)+vT.amount
end
end
end
for wT,xT in ipairs(hT)do
local yT,zT
if xT.ready and not xT.pinned and qT<2 and(P.evoBlocked[xT.uuid]or 0)<os.time()then
if xT.hidden and(xT.tierRank or 0)<ab.TIER_RANK.S then
yT=qtc[2241]
end
for AT,BT in ipairs(yT and{}or xT.items or{})do
if ab.have(BT.id)-BT.amount<(pT[BT.id]or 0)then
yT=string.format(qtc[2242],(H.Items[BT.id]or{}).name or BT.id)
break
end
end
yT=yT or P.evoEats(xT,mT)
if not yT then
local CT,ET=P.evolve(xT,qtc[2243]..(#(xT.eats or{})>0 and qtc[2244]or qtc[360]))
if CT then
qT,zT=qT+1,true
table.insert(rT,qtc[2117]..N.name(xT.from)..qtc[2245]..N.name(xT.to))
else
P.evoBlocked[xT.uuid]=os.time()+3600
yT=ET
end
end
if yT then
table.insert(rT,N.name(xT.from)..qtc[1720]..yT)
end
end
if not zT then
for FT,GT in ipairs(xT.items or{})do
pT[GT.id]=(pT[GT.id]or 0)+GT.amount
end
end
end
j.status(qtc[2239],#rT>0 and table.concat(rT,qtc[1623])or qtc[2246])
end
bb.BONUS=1.5
bb.SLOW=1.4
function bb.boost(HT,IT,JT,KT)
if IT<2 or JT>=math.min(I.dangerReach,(KT or 1)*0.9)then
return
end
local LT=JT<math.min(I.safeReach,(KT or 1)*0.75)
local NT=0
for OT,PT in ipairs(HT)do
if not PT.farm and not PT.train and PT.cost>0 then
NT=math.max(NT,PT.gain/PT.cost)
end
end
for QT,RT in ipairs(HT)do
if RT.train==qtc[2247]or(RT.train==qtc[2248]and LT)then
RT.gain=math.max(RT.gain,NT*RT.cost*1.05)
end
end
end
bb.HOLD_REACH=0.3
bb.ZONE=0.25
function bb.hold(TT,UT,VT)
if UT<2 or TT>=bb.HOLD_REACH+(VT and 0.1 or 0)then
return false
end
return true,string.format(qtc[2249],math.floor(TT*100+0.5))
end
function bb.same(WT,XT)
if#WT~= #XT then
return false
end
local YT={}
for ZT,_T in ipairs(WT)do
YT[_T]=true
end
for aU,bU in ipairs(XT)do
if not YT[bU]then
return false
end
end
return true
end
function bb.team()
local cU={}
for dU,eU in ipairs(N.equipped())do
table.insert(cU,eU.uuid)
