return nil
end
local gU,hU
local iU=I.autoEvolve and I.evolveUnit~=qtc[360]and I.evolveUnit or nil
for jU,kU in ipairs(J.goals or{})do
local lU,mU=nil,0
for nU,oU in ipairs(kU.plans or{})do
if oU.takedown then
lU=oU
else
mU=mU+1
end
end
local pU=lU and kU.intoTeam and(kU.pinned or not kU.unknown)and(not iU or kU.uuid==iU)and fU.collection:get_unit_by_uuid(kU.uuid)
if pU then
local qU=tonumber(lU.what==qtc[1912]and pU.total_kills or pU.total_takedowns)or 0
if qU<lU.need then
local rU=(mU==0 and 1000 or 0)+(tonumber(kU.tierRank)or 0)*10-jU*0.01
if not gU or rU>hU then
gU,hU={uuid=kU.uuid,id=kU.from,to=kU.to,what=lU.what,have=qU,need=lU.need},rU
end
end
end
end
return gU
end
function bb.realHave(sU)
