local uU=tU and tU.collection:get_unit_by_uuid(sU.uuid)
local vU=uU and tonumber(sU.what==qtc[1912]and uU.total_kills or uU.total_takedowns)or 0
return math.max(vU,sU.have+(sU.got or 0))
