function bb.bestInfinite()
local UU,VU
for WU,XU in ipairs(O.lastScored or{})do
if XU.kind==qtc[1450]and bb.eligible(XU)then
local YU,ZU=J.train.real[XU.key],XU.rec or O.rec(XU.key)
local _U=(tonumber(ZU.timed)or 0)>0 and ZU.sec/ZU.timed/60 or 0
local aV=(YU and YU.n>0 and _U>0)and(YU.sum/YU.n)/_U or 0
if aV<=0 then
aV=U.hiveTrainRate(XU.key)or 0
end
if aV>(VU or 0)then
UU,VU=XU,aV
end
end
end
