end
function bb.ratio()
local bV=J.train.cal
if not(bV and(bV.n or 0)>0 and(bV.sim or 0)>0)then
return 1
end
return M.clamp(bV.real/bV.sim,0.05,2)
end
function bb.perRun(cV,dV)
local eV=J.train.real[cV]
if eV and eV.n>0 then
return eV.sum/eV.n,true
end
local fV=U.hiveTrain(cV,dV)
if fV then
return fV,true
end
local gV,hV=0,0
local iV=O.isInf(cV)
for jV,kV in pairs(J.train.real)do
if O.isInf(jV)==iV then
gV,hV=gV+kV.sum,hV+kV.n
end
end
if hV>0 then
return gV/hV,true
end
local lV=J.trainSim[cV]
return lV and lV.tk and lV.tk*bb.ratio()or nil,false
end
function bb.eligible(mV)
if mV.kind==qtc[1583]or mV.kind==qtc[1445]then
return false,qtc[2250]
end
if mV.kind==qtc[1451]then
return false,qtc[2251]
