end
local nV=mV.rec or O.rec(mV.key)
if nV.runs>=3 and nV.wins/nV.runs<0.8 then
return false,qtc[2254]
end
local oV=J.simRes[mV.key]
if oV and oV.trust and not oV.trust.ok then
return false,qtc[2255]
end
return true
end
function bb.plan(pV,qV,rV)
local sV=H.session()
local tV=table.clone(rV)
table.sort(tV)
local uV=table.concat(tV,qtc[2028])
local vV=(tonumber((J.simCal[pV.key]or{}).n)or 0)>0
local wV=vV and 1.3 or 2
local xV=uV..qtc[2256]..qV.uuid..(vV and qtc[2257]or qtc[2258])..qtc[2259]
local yV=J.trainSim[pV.key]
if yV and yV.sig==xV and not yV.pending and os.time()-(yV.at or 0)<6*3600 then
return yV
end
local zV={sig=xV,base=uV,uuid=qV.uuid,at=os.time(),ok=false,margin=wV,pending=true}
J.trainSim[pV.key]=zV
local AV,BV=W.levelFor(pV)
if not AV then
zV.why,zV.pending=qtc[2260],nil
return zV
end
local CV=W.info(AV,pV.key,BV,pV.mod)
local DV={}
for EV,FV in ipairs(rV)do
local GV=sV.collection:get_unit_by_uuid(FV)
if GV then
table.insert(DV,GV)
end
end
local HV=sV.collection:get_unit_by_uuid(qV.uuid)
if not HV or#DV==0 then
zV.why,zV.pending=qtc[2261],nil
return zV
end
local IV=W.run(CV,W.teamFrom(DV,CV.map),{hpMul=1})
local JV=CV.infinite and W.unbound(AV)
local KV=JV and O.infTier(W.run(CV,W.teamFrom(DV,CV.map),{hpMul=wV}).wave)or nil
local LV={}
for MV,NV in ipairs(DV)do
if not N.isFarm(NV.unit_id)then
local OV,PV=pcall(N.score,NV,pV.mod)
table.insert(LV,{i=MV,sc=OV and PV or 0})
end
end
table.sort(LV,function(QV,RV)
return QV.sc<RV.sc
end)
local SV
for TV=1,math.min(3,#LV)do
local UV=table.clone(DV)
UV[LV[TV].i]=HV
local VV=W.teamFrom(UV,CV.map)
local WV=W.run(CV,VV,{hpMul=wV,train=qV.uuid})
if(JV and O.infTier(WV.wave)>=KV)or(not JV and WV.won)then
local XV=W.run(CV,VV,{hpMul=1,train=qV.uuid})
local YV=(XV.tk or 0)/math.max(0.5,XV.t/60)
if(XV.won or JV)and(not SV or YV>math.max(SV.rate*1.5,SV.rate+1))then
SV={out=DV[LV[TV].i].unit_id,r=XV,rate=YV,trial=UV}
end
end
end
zV.ownMin=IV.t/60
if not SV then
zV.why=JV and string.format(qtc[2262],KV,vV and qtc[2263]or qtc[2264])or vV and qtc[2265]or qtc[2266]
else
zV.out,zV.tk,zV.minutes=SV.out,SV.r.tk or 0,SV.r.t/60
zV.uuids={}
for ZV,_V in ipairs(SV.trial)do
table.insert(zV.uuids,_V.uuid)
end
zV.slow=(IV.won and not JV)and zV.minutes/math.max(0.1,zV.ownMin)or 1
if zV.tk<=0 and next(J.train.real)==nil then
zV.why=qtc[2267]
elseif zV.slow>bb.SLOW then
zV.why=string.format(qtc[2268],math.floor((zV.slow-1)*100+0.5))
else
zV.ok=true
end
end
zV.pending=nil
j.log(1,qtc[2269],string.format(qtc[2270],pV.label,N.name(qV.id),zV.out and(qtc[2271]..N.name(zV.out))or qtc[360],zV.ok and string.format(qtc[2272],math.floor((bb.perRun(pV.key,qV.id)or 0)+0.5),qV.what,zV.minutes,zV.ownMin)or tostring(zV.why)))
j.saveSoon()
return zV
end
