W.INF_CAP=80
function W.evaluate(Imb,Jmb)
local Kmb=W.run(Imb,Jmb,{hpMul=1})
local Lmb={won=Kmb.won,wave=Kmb.wave,minutes=Kmb.t/60,aliveAt=Kmb.aliveAt,total=Imb.total,at=os.time()}
if Imb.infinite and W.unbound(Imb.ld)then
Lmb.p=1
Lmb.margin=Kmb.won and string.format(qtc[2631],Imb.total)or string.format(qtc[2632],Kmb.wave,Kmb.t/60)
elseif Kmb.won then
local Mmb=W.run(Imb,Jmb,{hpMul=1.3})
Lmb.p=Mmb.won and 0.92 or 0.7
Lmb.margin=Mmb.won and qtc[2633]or qtc[2634]
else
local Nmb=W.run(Imb,Jmb,{hpMul=0.75})
Lmb.p=Nmb.won and 0.25 or 0.05
Lmb.margin=Nmb.won and string.format(qtc[2635],Kmb.wave)or string.format(qtc[2636],Kmb.wave,Imb.total)
if not Nmb.won then
local Omb=W.run(Imb,Jmb,{hpMul=0.25})
if not Omb.won then
Lmb.p,Lmb.hopeless=0.005,true
Lmb.margin=string.format(qtc[2637],Kmb.wave,Imb.total)
end
end
end
return Lmb
end
function W.trust(Pmb,Qmb)
local Rmb=Pmb.cal or{}
if type(Rmb.alive)~=qtc[1431]or Rmb.teamSig~=W.sig((function()
local Smb={}
for Tmb,Umb in ipairs(Qmb)do
table.insert(Smb,Umb.u)
end
return Smb
end)())then
return nil
end
if Pmb.key==qtc[1725]and not Rmb.aliveLvl then
return nil
end
if Rmb.aliveLvl and Pmb.ld and Pmb.ld.id and Rmb.aliveLvl~=tostring(Pmb.ld.id)..(eb.is(Pmb.ld.id)and(qtc[2638]..tostring(Pmb.ld.map))or qtc[360])then
return nil
end
local Vmb=W.run(Pmb,Qmb,{hpMul=1})
local Wmb,Xmb,Ymb=0,0,0
for Zmb=3,math.min(Vmb.wave,tonumber(Rmb.lastWave)or 99)do
local _mb=tonumber(Rmb.alive[tostring(Zmb)])
local anb=Vmb.aliveAt[Zmb]
if _mb and anb and _mb>0 then
Wmb=Wmb+_mb
Xmb=Xmb+anb
Ymb=Ymb+1
