W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local cnb=H.session()
local dnb,enb={},0
for fnb,gnb in pairs(cnb.profile_data.collection.owned_units)do
local hnb=gnb.unit_id
if not dnb[hnb]and H.Units[hnb]and not N.isFarm(hnb)and N.rows(hnb)and not N.hidden(hnb)then
local inb,jnb=pcall(H.USC.calculate_level,hnb,tonumber(gnb.xp)or 0)
if inb and(tonumber(jnb)or 0)>=W.GROWN_LEVEL then
dnb[hnb]=true
enb=enb+1
end
end
end
return enb
end
function W.pool(knb,lnb)
