local wnb=N.isFarm(snb.unit_id)
local xnb,ynb=pcall(wnb and function()
return N.farm(snb,N.rows(snb.unit_id).max)
end or N.score,snb,knb)
ynb=(xnb and ynb or 0)*(wnb and 1 or N.skinMul(snb,lnb and lnb.skinSet))
local znb=wnb and onb or nnb
if not znb[snb.unit_id]or ynb>znb[snb.unit_id].sc then
znb[snb.unit_id]={u=snb,sc=ynb}
end
end
end
