end
for Ynb=1,math.min(3,#Unb)do
table.insert(Knb,Unb[Ynb])
end
if lnb and((lnb.flyChance or 0)>0 or lnb.mapFly or(lnb.shield or 0)>0)then
local Znb,_nb={},{}
for aob=11,#Anb do
local bob=Anb[aob].u
local cob=N.rows(bob.unit_id)[0]
if N.airFrom(bob.unit_id)==0 then
table.insert(Znb,bob)
end
local dob,eob=tonumber(cob and cob.cd)or 0,tonumber((H.Units[bob.unit_id]or{}).cost)or 0
if dob>0 and eob>0 and N.range(bob,0)>=15 then
local fob=N.attackInfo(cob.atk,cob.range)
table.insert(_nb,{u=bob,v=fob.n*fob.hits/dob/eob*math.min(6,N.cap(bob))})
end
end
table.sort(_nb,function(gob,hob)
return gob.v>hob.v
end)
for iob=1,math.min(4,#Znb)do
table.insert(Knb,Znb[iob])
end
for job=1,math.min(6,#_nb)do
table.insert(Knb,_nb[job].u)
