function W.bestTeam(opb,ppb,qpb,rpb)
local spb=M.now()
rpb=rpb or 25
local tpb=table.clone(ppb)
local upb,vpb=W.cliff(opb,W.teamFrom(tpb,opb.map))
local function wpb(xpb)
local ypb=0
for zpb,Apb in ipairs(xpb)do
