end
local Bpb=wpb(qpb)>0
local function Cpb(Dpb)
local Epb=0
for Fpb,Gpb in ipairs(Dpb)do
if not N.isFarm(Gpb.unit_id)and not N.allyBuff(Gpb.unit_id)then
Epb=Epb+N.cap(Gpb)
end
end
return Epb
end
local Hpb
while#tpb<6 do
local Ipb,Jpb
local Kpb=Bpb and wpb(tpb)==0
for Lpb,Mpb in ipairs(qpb)do
local Npb=false
for Opb,Ppb in ipairs(tpb)do
if Ppb.unit_id==Mpb.unit_id then
Npb=true
end
end
if not Npb and(not Kpb or N.isFarm(Mpb.unit_id))then
local Qpb=table.clone(tpb)
table.insert(Qpb,Mpb)
local Rpb=W.run(opb,W.teamFrom(Qpb,opb.map),{hpMul=upb})
local Spb=W.objective(Rpb)
if not Jpb or Spb>Jpb then
Ipb,Jpb,Hpb=Mpb,Spb,Rpb
end
end
end
if not Ipb then
break
end
table.insert(tpb,Ipb)
end
if Bpb and wpb(tpb)==0 then
local Tpb,Upb
for Vpb=1,#tpb do
for Wpb,Xpb in ipairs(qpb)do
if N.isFarm(Xpb.unit_id)then
local Ypb=table.clone(tpb)
Ypb[Vpb]=Xpb
local Zpb=W.run(opb,W.teamFrom(Ypb,opb.map),{hpMul=upb})
local _pb=W.objective(Zpb)
if not Upb or _pb>Upb then
Tpb,Upb,Hpb=Ypb,_pb,Zpb
end
end
end
end
if Tpb then
tpb=Tpb
end
end
local function aqb(bqb,cqb)
local dqb=W.teamFrom(bqb,opb.map)
return(W.objective(cqb)+W.objective(W.run(opb,dqb,{hpMul=upb*0.92}))+W.objective(W.run(opb,dqb,{hpMul=upb*1.08})))/3
end
local eqb,fqb=Hpb or vpb,aqb(tpb,Hpb or vpb)
if type(qpb.rest)==qtc[1431]and#qpb.rest>0 then
local gqb,hqb
for iqb,jqb in ipairs(tpb)do
if not N.isFarm(jqb.unit_id)and not N.allyBuff(jqb.unit_id)then
local kqb,lqb=pcall(N.score,jqb,opb.mod)
lqb=(kqb and lqb or 0)*N.skinMul(jqb,opb.skinSet)
if not hqb or lqb<hqb then
gqb,hqb=iqb,lqb
end
end
end
if gqb then
local mqb,nqb={},M.now()
for oqb,pqb in ipairs(qpb.rest)do
if M.now()-nqb>5 then
break
end
local qqb=false
for rqb,sqb in ipairs(tpb)do
if sqb.unit_id==pqb.unit_id then
qqb=true
end
end
if not qqb then
local tqb=table.clone(tpb)
tqb[gqb]=pqb
table.insert(mqb,{u=pqb,o=W.objective(W.run(opb,W.teamFrom(tqb,opb.map),{hpMul=upb}))})
end
end
table.sort(mqb,function(uqb,vqb)
return uqb.o>vqb.o
end)
qpb=table.clone(qpb)
for wqb=1,math.min(4,#mqb)do
table.insert(qpb,1,mqb[wqb].u)
end
spb=spb+(M.now()-nqb)
end
end
for xqb=1,2 do
local yqb=false
for zqb=1,#tpb do
for Aqb,Bqb in ipairs(qpb)do
if M.now()-spb>rpb then
return tpb,eqb,upb,vpb
end
local Cqb=false
for Dqb,Eqb in ipairs(tpb)do
if Eqb.unit_id==Bqb.unit_id then
Cqb=true
end
end
if not Cqb then
local Fqb=table.clone(tpb)
Fqb[zqb]=Bqb
if(not Bpb or wpb(Fqb)>0)and Cpb(Fqb)>=math.min(8,Cpb(tpb))then
local Gqb=W.run(opb,W.teamFrom(Fqb,opb.map),{hpMul=upb})
local Hqb=W.objective(Gqb)
if Hqb>fqb+1 then
Hqb=aqb(Fqb,Gqb)
if Hqb>fqb+1 then
tpb,fqb,eqb,yqb=Fqb,Hqb,Gqb,true
end
end
end
end
end
end
if not yqb then
break
end
end
return tpb,eqb,upb,vpb
end
function W.evolutions()
