j.log(1,qtc[2644],string.format(qtc[2645],hrb.label,trb.margin,trb.calibrated and qtc[2646]or qtc[2647],trb.trust and string.format(qtc[2648],trb.trust.ratio)or qtc[2649]))
local wrb=O.rec(hrb.key)
if I.simTeams and irb and type(wrb.winTeam)==qtc[1431]and#wrb.winTeam>0 then
