if Brb then
table.insert(yrb,Brb)
end
end
if#yrb== #wrb.winTeam then
local Crb=W.teamFrom(yrb,orb.map)
local Drb=W.run(orb,Crb,{hpMul=1})
local Erb=W.trust(orb,Crb)
local Frb=Erb and not Erb.ok
if not Drb.won or Frb then
local Grb,Hrb={},{}
for Irb,Jrb in ipairs(yrb)do
table.insert(Grb,N.name(Jrb.unit_id))
table.insert(Hrb,Jrb.unit_id)
end
J.simTeam[hrb.key]={uuids=wrb.winTeam,names=Grb,ids=Hrb,won=true,wave=orb.total,better=W.sig(yrb)~=trb.sig,cur={won=trb.won,wave=trb.wave},at=os.time(),label=hrb.label,base=trb.sig,why=qtc[2650]}
j.log(1,qtc[2644],string.format(qtc[2651],hrb.label,table.concat(Grb,qtc[1527]),Frb and string.format((Erb.ratio or 0)<0.1 and qtc[2652]or qtc[2653],Erb.ratio or 0)or string.format(qtc[2654],Drb.wave),wrb.winTeamN or 1))
return trb
end
end
end
if I.simTeams and irb then
local Krb,Lrb,Mrb,Nrb,Orb=pcall(W.bestTeam,orb,prb,W.pool(nrb,orb),jrb)
if Krb and Lrb then
local Prb=W.sig(Lrb)~=trb.sig
if Prb and trb.won and(trb.p or 0)>=0.92 then
local Qrb={}
for Rrb,Srb in ipairs(Lrb)do
table.insert(Qrb,N.name(Srb.unit_id))
end
j.log(1,qtc[2644],string.format(qtc[2655],hrb.label,table.concat(Qrb,qtc[1527])))
Lrb,Prb=prb,false
end
local Trb=qtc[360]
if Prb then
local Urb,Vrb=W.exam(orb,prb)
local Wrb,Xrb=W.exam(orb,Lrb)
if Wrb>Urb or(Wrb==Urb and Xrb>Vrb)then
Trb=string.format(qtc[2656],Wrb,Urb)
else
local Yrb={}
for Zrb,_rb in ipairs(Lrb)do
table.insert(Yrb,N.name(_rb.unit_id))
end
j.log(1,qtc[2644],string.format(qtc[2657],hrb.label,table.concat(Yrb,qtc[1527]),Wrb,Urb))
Lrb,Prb=prb,false
end
end
local asb=W.run(orb,W.teamFrom(Lrb,orb.map),{hpMul=1})
if Prb then
trb.playing=asb.won and qtc[2658]or string.format(qtc[2659],asb.wave,orb.total)
end
local bsb,csb={},{}
for dsb,esb in ipairs(Lrb)do
table.insert(bsb,esb.uuid)
table.insert(csb,N.name(esb.unit_id))
end
local fsb={}
for gsb,hsb in ipairs(Lrb)do
table.insert(fsb,hsb.unit_id)
end
J.simTeam[hrb.key]={uuids=bsb,names=csb,ids=fsb,won=asb.won,wave=asb.wave,better=Prb,cur={won=trb.won,wave=trb.wave},at=os.time(),label=hrb.label,base=trb.sig}
j.log(1,qtc[2644],string.format(qtc[2660],hrb.label,asb.won and qtc[1773]or(qtc[2661]..asb.wave),table.concat(csb,qtc[1527]),Prb and(string.format(qtc[2662],Nrb,Mrb.won and qtc[1773]or qtc[1774],Mrb.wave,Orb.won and qtc[1773]or qtc[1774],Orb.wave)..Trb)or qtc[2663]))
local isb={}
for jsb,ksb in ipairs(W.evolutions())do
