end
end
end
if qsb then
msb[qsb]=ksb.evolved
end
end
local wsb=W.run(orb,W.teamFrom(msb,orb.map),{hpMul=1})
if wsb.won and not asb.won then
lsb=qtc[2664]..hrb.label..qtc[2665]
elseif wsb.wave>asb.wave then
lsb=string.format(qtc[2666],hrb.label,wsb.wave,asb.wave)
elseif wsb.won and asb.won and wsb.t<asb.t-6 then
lsb=string.format(qtc[2667],hrb.label,(asb.t-wsb.t)/60)
else
lsb=asb.won and(qtc[2668]..hrb.label..qtc[2669])or(qtc[2670]..hrb.label)
end
end
table.insert(isb,{from=N.name(ksb.from),to=N.name(ksb.to),ready= #ksb.missing==0,missing=ksb.missing[1],gain=lsb,mode=hrb.label})
end
J.simEvo=isb
end
end
j.saveSoon()
return trb
end
