j.log(1,qtc[2911],string.format(qtc[2920],N.name(eOb.id),Q.spotKey(hOb),iOb,fOb))
Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=eOb.id,x=math.floor(hOb.X),z=math.floor(hOb.Z),cover=math.floor((iOb or 0)+0.5),why=tostring(fOb):sub(1,90)})
