local NOb=workspace:FindFirstChild(qtc[2927])
if NOb and zOb>0 then
wOb.timer[tostring(zOb)]=math.max(wOb.timer[tostring(zOb)]or 0,tonumber(NOb.Value)or 0)
end
local OOb=AOb-(Q.lastMoneyR or AOb)
Q.lastMoneyR=AOb
Q.incomeLog=Q.incomeLog or{}
if OOb>0 then
table.insert(Q.incomeLog,{t=yOb,y=OOb})
end
while Q.incomeLog[1]and yOb-Q.incomeLog[1].t>30 do
table.remove(Q.incomeLog,1)
end
local POb=0
for QOb,ROb in ipairs(Q.incomeLog)do
POb=POb+ROb.y
end
local SOb=math.min(30,yOb-(Q.startT or yOb))
Q.incomeRate=SOb>=8 and POb/SOb or nil
for TOb,UOb in ipairs(Q.enemies)do
