local WOb=Q.track[VOb]
if not WOb then
local XOb=VOb._stats
local YOb=VOb:FindFirstChildOfClass(qtc[2855])
local ZOb=xOb.cfgById[XOb.id.Value]
local _Ob=ZOb and W.baseStats(xOb,ZOb)
if YOb and _Ob and zOb>0 then
