function Q.holdGain(sSb,tSb)
if Q.random or not tSb or not Q.info then
return 0
end
local uSb=N.attackInfo(tSb.atk,tSb.range)
if(uSb.stun or 0)<=0 and(uSb.slowTime or 0)<=0 then
return 0
end
local vSb=0
for wSb,xSb in ipairs(Q.mine or{})do
local ySb=xSb._stats
local zSb=N.rows(ySb.id.Value)
local ASb=zSb and zSb[math.min(ySb.upgrade.Value,zSb.max)]
local BSb=ASb and ASb.atk and N.attackInfo(ASb.atk,ASb.range)
if BSb and((BSb.stun or 0)>0 or(BSb.slowTime or 0)>0)then
vSb=vSb+1
end
end
local CSb,DSb=W.mask(Q.info.map,N.range(sSb.u,0)*(Q.info.rangeScale or 1)),0
for ESb=1,W.BINS do
if CSb[ESb]then
DSb=DSb+1
end
end
local FSb=Q.depth and Q.depth.units>0 and Q.depth.covEnd or 1
local GSb=(N.airFrom(sSb.id)==0)and 1 or(1-(1-H.FLY_GROUND)*math.min(1,Q.info.flyChance or 0))
return V.holdGain(uSb,Q.teamDps or 0,DSb/(math.max(0.1,FSb)*W.BINS)*GSb,vSb)
end
function Q.buffGain(HSb)
local ISb=N.allyBuff(HSb.id)
if not ISb then
return 0
end
local JSb=Q.buffShort(ISb)
local KSb=J.stack[ISb.attack]
local LSb=KSb and KSb.stacks and(KSb.cap or 1)or nil
local MSb,NSb=pcall(N.range,HSb.u,0)
NSb=(MSb and tonumber(NSb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local OSb=0
for PSb,QSb in ipairs(JSb)do
local RSb=0
for SSb,TSb in ipairs(JSb)do
if(TSb.pos-QSb.pos).Magnitude<=NSb then
local USb=ISb.types[TSb.base]
local VSb=USb*ISb.uptime
if LSb then
VSb=math.max(0,math.min(LSb,(TSb.n+1)*USb*ISb.uptime)-math.min(LSb,TSb.n*USb*ISb.uptime))
end
RSb=RSb+TSb.dps*VSb
end
end
OSb=math.max(OSb,RSb)
