function Q.blessGain(cTb)
if not N.BLESS.by[cTb.id]then
return 0
end
local dTb,eTb=0,0
for fTb,gTb in ipairs(Q.mine or{})do
local hTb=gTb._stats.id.Value
if N.BLESS.by[hTb]then
dTb=dTb+1
