function Q.learn()
local CZb,DZb={},{}
local EZb,FZb=0,0
for GZb,HZb in ipairs(Q.mine)do
local IZb=HZb._stats
local JZb=IZb.id.Value
local KZb=IZb:FindFirstChild(qtc[2929])and IZb.total_damage.Value or 0
if not N.isFarm(JZb)then
