DZb[JZb]=(DZb[JZb]or 0)+Q.liveDps(HZb,JZb)/math.max(0.5,N.nudge(JZb))
local LZb=N.passive(JZb).mark
if LZb then
DZb[JZb]=DZb[JZb]+LZb.dot*IZb.damage.Value
end
EZb=EZb+KZb
end
end
for MZb,NZb in pairs(DZb)do
FZb=FZb+NZb
end
if EZb<=0 or FZb<=0 then
return
end
Q.lastEff={}
for OZb,PZb in pairs(CZb)do
local QZb,RZb=PZb/EZb,DZb[OZb]/FZb
if RZb>0.02 then
local SZb=J.learn[OZb]or{eff=1,n=0}
local TZb=math.max(0.02,0.25*math.sqrt(30/(30+SZb.n)))
local UZb=M.clamp(QZb/RZb,0.3,3)
Q.lastEff[OZb]=math.floor(UZb*1000+0.5)/1000
SZb.eff=SZb.eff+(UZb-SZb.eff)*TZb
SZb.n=SZb.n+1
J.learn[OZb]=SZb
end
end
end
