table.insert(fcc.r,ecc)
while#fcc.r>80 do
table.remove(fcc.r,1)
end
local gcc=W.modRead(fcc)
local hcc=fcc.said and gcc and math.abs(gcc-fcc.said)<=fcc.said*0.1
if gcc and not hcc then
fcc.said=gcc
end
local icc,jcc=dcc==qtc[2614]and qtc[3254]or(dcc==qtc[1640]and qtc[3255]or qtc[2615]),dcc==qtc[2614]and qtc[3256]or qtc[3257]
if gcc and not hcc then
j.log(1,qtc[2838],string.format(qtc[3258],icc,#fcc.r,gcc,jcc))
end
if gcc==false and not fcc.saidLoose then
fcc.saidLoose=true
local kcc=table.clone(fcc.r)
table.sort(kcc)
j.log(1,qtc[2838],string.format(qtc[3259],icc,#kcc,kcc[1],kcc[#kcc]))
end
end
